import bpy,pathlib,json,hashlib
P=pathlib.Path(__file__).resolve().parents[1];O=P/'renders/R12';O.mkdir(exist_ok=True);records=[]
for version in ['R11','R12']:
 for mode in ['material','white']:
  model=P/'models'/f'{version}_{mode}.blend';bpy.ops.wm.open_mainfile(filepath=str(model));s=bpy.context.scene;s.camera=bpy.data.objects['TABLE_high'];s.render.engine='CYCLES';s.cycles.samples=64;s.cycles.use_denoising=False;s.render.resolution_x=1192;s.render.resolution_y=671;s.render.resolution_percentage=100;s.render.threads_mode='FIXED';s.render.threads=2;f=O/f'{version}_{mode}_TABLE_high.png';assert not f.exists();s.render.filepath=str(f);bpy.ops.render.render(write_still=True);records.append({'path':str(f.relative_to(P)),'bytes':f.stat().st_size,'sha256':hashlib.sha256(f.read_bytes()).hexdigest(),'model':str(model.relative_to(P)),'model_sha256':hashlib.sha256(model.read_bytes()).hexdigest(),'camera':'TABLE_high','camera_matrix':[list(r) for r in s.camera.matrix_world],'lens':s.camera.data.lens,'resolution':[1192,671],'samples':64,'denoise':False,'threads':2,'scope':'one synthetic table layout view, not source registration; original models not modified for rendering'});(P/'qa/R12-render-records.json').write_text(json.dumps(records,indent=2))
